// import and run Promise polyfill first
import { polyfill as PromisePolyfill } from "es6-promise";
PromisePolyfill();

// Imports and registers
import { HMIWebExperionServicesUnitTimeline } from "@hw/experionservices/unbundled/HMIWebExperionServicesUnitTimeline";
import { UnitTimelineElement } from "@hw/hmiweb-unittimeline/unbundled/index";
import { HmiwebTsLogger } from "@hw/hmiweb-core/js/logging/HmiwebTsLogger";
import { HmiwebTsLocalisation } from "@hw/hmiweb-core/js/localisation/HmiwebTsLocalisation";
import { HmiwebTsLocalStorage } from "@hw/hmiweb-core/js/utils/HmiwebTsLocalStorage";

HmiwebTsLocalStorage.register(HmiwebTsLogger.instance);
let storage = new HmiwebTsLocalStorage();

let service = new HMIWebExperionServicesUnitTimeline();
service.register(HmiwebTsLogger.simpleInstance);
UnitTimelineElement.register(HmiwebTsLogger.instance, HmiwebTsLocalisation.instance, service.unitTimelineService, storage);

window.addEventListener("unload", () => {
    service.dispose();
    service = null;
    storage = null;
});
